import React, { useEffect, useState } from 'react';
import { useParams, Link as RouterLink } from 'react-router-dom';
import {
    Box, Typography, Container, Grid, Paper, Button, Chip, CircularProgress,
    List, ListItem, ListItemIcon, ListItemText, Breadcrumbs, Link,
    IconButton, useTheme, Table, TableBody, TableCell, TableHead, TableRow, Alert
} from '@mui/material';
import { useMosqueContext } from '../contexts/MosqueContext';
import { getMasjid, MASJID_SIGNUP_EMAIL } from '../services/masjidService';
import HomeIcon from '@mui/icons-material/Home';
import MosqueIcon from '@mui/icons-material/Mosque';
import LocationOnIcon from '@mui/icons-material/LocationOn';
import DirectionsIcon from '@mui/icons-material/Directions';
import PhoneIcon from '@mui/icons-material/Phone';
import LanguageIcon from '@mui/icons-material/Language';
import EmailIcon from '@mui/icons-material/Email';
import CampaignIcon from '@mui/icons-material/Campaign';
import VerifiedIcon from '@mui/icons-material/Verified';
import FavoriteIcon from '@mui/icons-material/Favorite';
import FavoriteBorderIcon from '@mui/icons-material/FavoriteBorder';

const PRAYER_LABELS = { fajr: 'Fajr', dhuhr: 'Dhuhr', asr: 'Asr', maghrib: 'Maghrib', isha: 'Isha' };

// Staff-entered "HH:MM" (24h) -> "1:30 PM".
const to12h = (hhmm) => {
    const match = /^(\d{1,2}):(\d{2})$/.exec(String(hhmm || ''));
    if (!match) return hhmm || '';
    const h = Number(match[1]);
    return `${h % 12 || 12}:${match[2]} ${h < 12 ? 'AM' : 'PM'}`;
};

// Only http(s) links from staff-entered data.
const safeWebsite = (url) => {
    if (!url) return null;
    const href = /^https?:\/\//i.test(url) ? url : `https://${url}`;
    try { return ['http:', 'https:'].includes(new URL(href).protocol) ? href : null; } catch { return null; }
};

const MosqueDetailPage = () => {
    const { id } = useParams();
    const theme = useTheme();
    const { toggleFavorite, favorites } = useMosqueContext();
    const [data, setData] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        window.scrollTo(0, 0);
        let cancelled = false;
        setLoading(true);
        setError(null);
        getMasjid(id)
            .then((d) => { if (!cancelled) setData(d); })
            .catch((err) => {
                console.error('Failed to load masjid:', err);
                if (!cancelled) setError(err.status === 404 ? 'not-found' : 'failed');
            })
            .finally(() => { if (!cancelled) setLoading(false); });
        return () => { cancelled = true; };
    }, [id]);

    if (loading) {
        return (
            <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', flexDirection: 'column', minHeight: '60vh' }}>
                <CircularProgress size={60} />
                <Typography sx={{ mt: 2 }}>Loading masjid...</Typography>
            </Box>
        );
    }

    if (error || !data?.masjid) {
        return (
            <Container maxWidth="sm" sx={{ py: 10, textAlign: 'center' }}>
                <MosqueIcon sx={{ fontSize: 60, color: theme.palette.text.secondary, opacity: 0.5, mb: 2 }} />
                <Typography variant="h5" gutterBottom>
                    {error === 'failed' ? 'We could not load this masjid right now.' : 'Masjid not found'}
                </Typography>
                <Button variant="contained" component={RouterLink} to="/mosque-directory" sx={{ mt: 2 }}>
                    Back to the directory
                </Button>
            </Container>
        );
    }

    const { masjid, today } = data;
    const masjidId = String(masjid.id);
    const isFavorite = favorites.includes(masjidId);
    const website = safeWebsite(masjid.website);
    const where = [masjid.address, masjid.address ? null : masjid.city].filter(Boolean).join(', ');
    const directionsHref = masjid.latitude != null && masjid.longitude != null
        ? `https://www.google.com/maps/search/?api=1&query=${masjid.latitude},${masjid.longitude}`
        : `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent([masjid.name, where].filter(Boolean).join(', '))}`;
    const jumuah = today?.isFriday && today.jumuah?.length
        ? today.jumuah.map((j) => ({ ...j, display: j.time12 }))
        : (masjid.jumuah || []).map((j) => ({ ...j, display: to12h(j.time) }));
    const hasIqamah = (today?.prayers || []).some((p) => p.iqamah);
    const correctionHref = `mailto:${MASJID_SIGNUP_EMAIL}?subject=${encodeURIComponent(`Correction: ${masjid.name}`)}`;

    return (
        <>
            <Box
                sx={{
                    background: `linear-gradient(135deg, ${theme.palette.primary.main}, ${theme.palette.primary.dark})`,
                    color: 'white',
                    pt: 8,
                    pb: 6
                }}
            >
                <Container maxWidth="lg">
                    <Breadcrumbs aria-label="breadcrumb" sx={{ color: 'rgba(255, 255, 255, 0.7)', mb: 2 }}>
                        <Link component={RouterLink} to="/" sx={{ display: 'flex', alignItems: 'center', color: 'inherit', '&:hover': { color: 'white' } }}>
                            <HomeIcon sx={{ mr: 0.5 }} fontSize="inherit" />
                            Home
                        </Link>
                        <Link component={RouterLink} to="/mosque-directory" sx={{ color: 'inherit', '&:hover': { color: 'white' } }}>
                            Mosque Directory
                        </Link>
                        <Typography color="white">{masjid.name}</Typography>
                    </Breadcrumbs>
                    <Box sx={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 2 }}>
                        <Typography variant="h3" component="h1" fontWeight="500" sx={{ fontSize: { xs: '2rem', md: '3rem' } }}>{masjid.name}</Typography>
                        <IconButton
                            onClick={() => toggleFavorite(masjidId)}
                            aria-label={isFavorite ? 'Remove from favorites' : 'Add to favorites'}
                            sx={{ color: 'white' }}
                        >
                            {isFavorite ? <FavoriteIcon /> : <FavoriteBorderIcon />}
                        </IconButton>
                    </Box>
                    {where && (
                        <Typography sx={{ mt: 1, opacity: 0.9, display: 'flex', alignItems: 'center' }}>
                            <LocationOnIcon fontSize="small" sx={{ mr: 0.5 }} />
                            {where}
                        </Typography>
                    )}
                    <Chip
                        icon={<VerifiedIcon sx={{ color: 'white !important' }} />}
                        label="Times kept up to date by the masjid"
                        sx={{ mt: 2, color: 'white', borderColor: 'rgba(255,255,255,0.6)' }}
                        variant="outlined"
                    />
                </Container>
            </Box>

            <Container maxWidth="lg" sx={{ py: 6 }}>
                <Grid container spacing={4}>
                    <Grid item xs={12} md={8}>
                        {(masjid.announcements || []).length > 0 && (
                            <Paper elevation={2} sx={{ p: 3, mb: 4, borderRadius: 2 }}>
                                <Typography variant="h6" gutterBottom sx={{ display: 'flex', alignItems: 'center' }}>
                                    <CampaignIcon sx={{ mr: 1 }} color="primary" />
                                    Announcements
                                </Typography>
                                {masjid.announcements.map((a) => (
                                    <Alert key={a.id} severity="info" icon={false} sx={{ mb: 1, whiteSpace: 'pre-line' }}>
                                        {a.text}
                                    </Alert>
                                ))}
                            </Paper>
                        )}

                        <Paper elevation={2} sx={{ p: 3, mb: 4, borderRadius: 2 }}>
                            <Typography variant="h6" gutterBottom>
                                Prayer times{today?.weekday ? ` — ${today.weekday}` : ''}{today?.date ? `, ${today.date}` : ''}
                            </Typography>
                            <Table size="small" aria-label="Today's prayer times">
                                <TableHead>
                                    <TableRow>
                                        <TableCell>Prayer</TableCell>
                                        <TableCell>Athan</TableCell>
                                        {hasIqamah && <TableCell>Iqamah</TableCell>}
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    {(today?.prayers || []).map((p) => (
                                        <TableRow key={p.prayer}>
                                            <TableCell sx={{ fontWeight: 500 }}>
                                                {p.jumuah ? "Dhuhr (Jumu'ah)" : PRAYER_LABELS[p.prayer] || p.prayer}
                                            </TableCell>
                                            <TableCell>{p.athan?.time12 || '—'}</TableCell>
                                            {hasIqamah && <TableCell>{p.iqamah?.time12 || '—'}</TableCell>}
                                        </TableRow>
                                    ))}
                                </TableBody>
                            </Table>
                            {today?.timezone && (
                                <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1 }}>
                                    Local time at the masjid ({today.timezone}).
                                </Typography>
                            )}
                        </Paper>

                        {jumuah.length > 0 && (
                            <Paper elevation={2} sx={{ p: 3, mb: 4, borderRadius: 2 }}>
                                <Typography variant="h6" gutterBottom>Jumu&rsquo;ah</Typography>
                                <List dense>
                                    {jumuah.map((j, i) => (
                                        <ListItem key={`${j.time}-${i}`} disableGutters>
                                            <ListItemText
                                                primary={j.display}
                                                secondary={[j.label, j.language].filter(Boolean).join(' · ') || null}
                                            />
                                        </ListItem>
                                    ))}
                                </List>
                            </Paper>
                        )}
                    </Grid>

                    <Grid item xs={12} md={4}>
                        <Paper elevation={2} sx={{ p: 3, mb: 4, borderRadius: 2 }}>
                            <Typography variant="h6" gutterBottom>Contact</Typography>
                            <List dense>
                                {where && (
                                    <ListItem disableGutters>
                                        <ListItemIcon sx={{ minWidth: 36 }}><LocationOnIcon /></ListItemIcon>
                                        <ListItemText primary={where} />
                                    </ListItem>
                                )}
                                {masjid.phone && (
                                    <ListItem disableGutters component="a" href={`tel:${masjid.phone.replace(/[^\d+]/g, '')}`} sx={{ color: 'inherit' }}>
                                        <ListItemIcon sx={{ minWidth: 36 }}><PhoneIcon /></ListItemIcon>
                                        <ListItemText primary={masjid.phone} />
                                    </ListItem>
                                )}
                                {masjid.email && (
                                    <ListItem disableGutters component="a" href={`mailto:${masjid.email}`} sx={{ color: 'inherit' }}>
                                        <ListItemIcon sx={{ minWidth: 36 }}><EmailIcon /></ListItemIcon>
                                        <ListItemText primary={masjid.email} sx={{ wordBreak: 'break-all' }} />
                                    </ListItem>
                                )}
                                {website && (
                                    <ListItem disableGutters component="a" href={website} target="_blank" rel="noopener noreferrer" sx={{ color: 'inherit' }}>
                                        <ListItemIcon sx={{ minWidth: 36 }}><LanguageIcon /></ListItemIcon>
                                        <ListItemText primary={website.replace(/^https?:\/\//i, '').replace(/\/$/, '')} sx={{ wordBreak: 'break-all' }} />
                                    </ListItem>
                                )}
                            </List>
                            <Button
                                fullWidth
                                variant="contained"
                                startIcon={<DirectionsIcon />}
                                href={directionsHref}
                                target="_blank"
                                rel="noopener noreferrer"
                                sx={{ mt: 1 }}
                            >
                                Directions
                            </Button>
                        </Paper>

                        <Paper elevation={0} variant="outlined" sx={{ p: 3, borderRadius: 2 }}>
                            <Typography variant="subtitle1" gutterBottom fontWeight={500}>Follow on Alexa</Typography>
                            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                Get this masjid&rsquo;s iqamah and Jumu&rsquo;ah reminders on your Echo with the Muslim Companion skill.
                            </Typography>
                            <Button variant="outlined" component={RouterLink} to="/alexa-skill/" fullWidth>
                                Muslim Companion for Alexa
                            </Button>
                            <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 2 }}>
                                Something wrong? <Link href={correctionHref}>Tell us</Link>.
                            </Typography>
                        </Paper>
                    </Grid>
                </Grid>
            </Container>
        </>
    );
};

export default MosqueDetailPage;
